# Verified answer key with detailed explanations. Dot-sourced by gh-600-build-quiz.ps1
$YNC = '<table class="yn"><tr><th>Statement</th><th>Answer</th></tr>{0}</table>'
function YN($rows) {
  ($rows | ForEach-Object { "<tr><td>$($_[0])</td><td class=`"ynv $($_.ToLower())`">$($_[1])</td></tr>" }) -join ''
}
function L($letter, $body) { "Correct answer: <b>$letter</b>$body" }
function WHY($t) { "<div class=`"why`">$t</div>" }
function WN($items) { "<span class=`"whead`">Why the others are wrong:</span><ul>" + (($items | ForEach-Object { "<li>$_</li>" }) -join '') + "</ul>" }

